head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
        txb_ISU_NM.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_2);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
    txb_TotalCnt1.hide();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20800.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_ProdList_OnLoadError
 * @description dts_ProdList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ProdList);
        dts_FileList.removeAll();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20800.dts_ProdList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ProdList_OnLoadCompleted
 * @description dts_ProdList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ProdList.errorMsg) {
            await $c.win.alert(dts_ProdList.errorMsg);
        }
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        dts_FileList.removeAll();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20800.dts_ProdList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ProdList_OnRowPosChanged
 * @description Prod List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdList_OnRowPosChanged = async function(row) {
    try {
        if (row > 0) {
            // 첨부파일목록조회
            await scwin.ins_searchFileList();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20800.dts_ProdList_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_FileList_OnLoadError
