/**
 * @method
 * @name grd_FileList_OnDblClick
 * @description grd_FileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_FileList_OnDblClick = function(row, colid) {
    try {
        if (dts_FileList.getRowStatus(dts_FileList.getRowPosition()) === 0 || dts_FileList.getRowStatus(dts_FileList.getRowPosition()) === 3) {
            scwin.downloadFile();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20800.grd_FileList_OnDblClick" });
    }
};

