///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description ins search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs("ins_Search");

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ProdList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ProdList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_searchFileList
 * @description ins search File List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_searchFileList = async function() {
    // 데이터셋 초기화
    scwin.initDs("ins_searchFileList");

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_searchFileList")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_FileList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_FileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_SaveFile
 * @description 첨부파일 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_SaveFile = async function() {
    // 조회조건 체크.
    if (!await scwin.chkValid("ins_SaveFile")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/FileInfoAction.do",
        ref : "dts_FileList",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {

};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_STD_CD_GRNT_DD.setValue(vCurDate.substr(0, 6) + "01");
    edt_TO_STD_CD_GRNT_DD.setValue(vCurDate);
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @param {*} pFg pFg
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function(pFg) {
    if (pFg === "ins_search") {
        dts_ProdList.removeAll();
        dts_FileList.removeAll();
        txb_TotalCnt.setValue("총 0건");
        txb_TotalCnt1.setValue("총 0건");
    } else if (pFg === "ins_searchFileList") {
        dts_FileList.removeAll();
        txb_TotalCnt1.setValue("총 0건");
    }
};

/**
 * @method
 * @name addFile
 * @description 파일추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addFile = async function() {
    if (dts_ProdList.getRowPosition() < 1) {
        // alert("선택된 상품이 없습니다.");
        return;
    }
    dts_FileList.insertRow();
    inf_find.open();
    const strFile = inf_find.getValue();
    const strFile_ext = strFile.substring(strFile.length - 3, strFile.length);
    if (strFile_ext === "exe") {
        await $c.win.alert("파일업로드 대상 확장자 파일이 아닙니다.");
        dts_FileList.removeRow(dts_FileList.getRowPosition());
        return;
    }
    if (inf_find.getValue() !== "") {
        // 데이터 세팅.
        let nRow = dts_FileList.getRowPosition();
        dts_FileList.setCellData(nRow, "STD_CD_APPL_ID", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "STD_CD_APPL_ID"));
        dts_FileList.setCellData(nRow, "KIND", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "KIND"));
        dts_FileList.setCellData(nRow, "ISU_NM", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "ISU_NM"));

        // 파일정보 세팅.
        dts_FileList.setCellData(nRow, "SAVE_FILE_NM", inf_find.getValue());
    } else {
        dts_FileList.removeRow(dts_FileList.getRowPosition());
    }
};

/**
 * @method
 * @name deleteFile
 * @description 파일삭제
 * @returns {void}
 * @hidden N
 */
scwin.deleteFile = function() {
    if (dts_FileList.getRowPosition() < 1) {
        return;
    }
    dts_FileList.removeRow(dts_FileList.getRowPosition());
};

/**
 * @method
 * @name downloadFile
 * @description 파일다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.downloadFile = function(attach_seq) {
    $c.stf.doLogSave("ULDINS20800.xml", SCREN_PROCS_TP_CD_08);
    let nRow = dts_FileList.getRowPosition();
    const sKEY1 = dts_FileList.getCellData(nRow, "STD_CD_APPL_ID");
    const sKEY2 = dts_FileList.getCellData(nRow, "ATTACH_FILE_NO");
    const sTmp = dts_FileList.getCellData(nRow, "KIND");
    let sGubun = "";
    if (sTmp === "발행기관") {
        sGubun = "1";
    } else {
        sGubun = "2";
    }
    location.href = "/filedownload.do?KEY1=" + sKEY1 + "&KEY2=" + sKEY2 + "&GUBUN=" + sGubun;
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "ins_Search") {
        if (edt_FROM_STD_CD_GRNT_DD.getValue() === "") {
            await $c.win.alert("표준코드부여 시작일를 입력하세요.");
            edt_FROM_STD_CD_GRNT_DD.focus();
            return false;
        }
        if (edt_TO_STD_CD_GRNT_DD.getValue() === "") {
            await $c.win.alert("표준코드부여 종료일을 입력하세요.");
            edt_TO_STD_CD_GRNT_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) === false) {
            return false;
        }

        // 체크된것이 하나도 없으면 전체선택 체크
        scwin.ctrlChbALL();
    } else if (pGubun === "ins_SaveFile") {
        if (!$c.cp.isModified(dts_FileList)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name ctrlChbALL
 * @description 채권 ~ 발행기관 체크박스 중 하나라도 체크되었다면 전체선택은 체크 해제. 아무것도 체크되어있지 않다면 전체선택 체크
 * @returns {void}
 * @hidden N
 */
scwin.ctrlChbALL = function() {
    if (chb_BND.getValue() === "N" &&
        chb_ELSDLS.getValue() === "N" &&
        chb_STKCERT.getValue() === "N" &&
        chb_BENFCERT.getValue() === "N" &&
        chb_SUBSRGHT.getValue() === "N" &&
        chb_DR.getValue() === "N" &&
        chb_CORPBND.getValue() === "N" &&
        chb_CP.getValue() === "N" &&
        chb_CD.getValue() === "N" &&
        chb_STRIP.getValue() === "N" &&
        chb_ISUR.getValue() === "N" &&
        chb_ETN.getValue() === "N") {
        chb_ALL.setValue("Y");
    } else {
        chb_ALL.setValue("N");
    }
};

/**
 * @method
 * @name ctrlChbEtc
 * @description 전체선택이 체크되면 나머지는 언체크
 * @returns {void}
 * @hidden N
 */
scwin.ctrlChbEtc = function() {
    if (chb_ALL.getValue() === "Y") {
        chb_BND.setValue("N");
        chb_ELSDLS.setValue("N");
        chb_STKCERT.setValue("N");
        chb_BENFCERT.setValue("N");
        chb_SUBSRGHT.setValue("N");
        chb_DR.setValue("N");
        chb_CORPBND.setValue("N");
        chb_CP.setValue("N");
        chb_CD.setValue("N");
        chb_STRIP.setValue("N");
        chb_ISUR.setValue("N");
        chb_ETN.setValue("N");
    }
};
